bg=4
G=[[4]*13 for _ in range(20)]
# Keep the original source motif
for r,row in {11:{7:5,8:5},12:{6:8,7:5,8:8},13:{6:8,7:5,8:0}}.items():
    for c,v in row.items(): G[r][c]=v
stamp=[[4,5,5],[8,5,8],[8,5,0]]
anchors=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
for r,c in anchors:
    for dr in range(3):
        for dc in range(3):
            v=stamp[dr][dc]
            if v != bg: G[r+dr-1][c+dc-1]=v
print('\n'.join(str(row) for row in G))
